// R631: R630 said "zero orphans: all 189 tools are mentioned". 41 of the 51 evidence-only tools are mentioned ONLY by index
// machinery — SCRIPT-INDEX, TOPIC-INDEX, STATUS, and R628–R630's own documents. The mention was generated by the record, not by a
// use of the tool.
//
// THE MEASUREMENT
//       evidence-only tools                                    51
//       mentioned ONLY in generated indexes / STATUS           41
//       mentioned in a round-specific evidence document        10
//
//   A `SCRIPT-INDEX.md` line reading "- `proof-r389-held-withdrawn.cjs` 被引用" is not a use. It is the index reporting the tool
//   exists. Counting it as coverage is the same circularity as making a citation that proves itself.
//
// WHY R630 WAS WRONG, PRECISELY
//   R630 measured "mentioned as a whole token outside tools/" — a property every generated index satisfies BY CONSTRUCTION, since
//   building the index requires listing every tool. So 189/189 was true and uninformative: an index cannot fail to mention a tool
//   it enumerates.
//
//   The corrected question is whether a tool appears in a document that exists for a reason OTHER than enumerating tools. On that
//   question, 41 have no such mention and 10 do.
//
// WHAT THE 41 ARE
//   Mostly `proof-*` and `probe-*` one-shots: `proof-consent-hidden`, `proof-packaged-cli-mcp`, `probe-regwrite`,
//   `probe-main-write`, `official-oauth-constants`. Each was written for one measurement, ran once, and left no round document
//   citing it — the round's evidence describes the FINDING without naming the script.
//
//   That is a traceability gap in the record, not a defect in the tools: a reader cannot follow a name from a finding back to a
//   script, because the name is only in the inventory.
//
// WHAT IS NOT CLAIMED
//   Not that the 41 are broken or unused: they ran, and several produced findings that ARE recorded. What is missing is the link.
//   Not that STATUS.md should be excluded in general: a block saying "ran tools/x.cjs and it reported N" IS a use. The 41 are the
//   ones where no STATUS line does that — only the enumeration does.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { COVERAGE, GAP, CIRCULARITY } from '../desktop/index-circularity.cjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

const GENERATED = /^(SCRIPT-INDEX|TOPIC-INDEX|orphan-tools-r630|never-executed-sweep-r629|broken-instrument-r628|STATUS)\.md$/;

const scan = () => {
  const TOOLS = path.join(ROOT, 'tools');
  const EV = path.join(ROOT, 'evidence');
  const TEST = path.join(ROOT, 'test');
  const testCorpus = fs.readdirSync(TEST).filter((f) => f.endsWith('.mjs'))
    .map((f) => fs.readFileSync(path.join(TEST, f), 'utf8')).join('\n');
  const all = fs.readdirSync(TOOLS).filter((f) => f.endsWith('.cjs'));
  const evidenceFiles = fs.readdirSync(EV).filter((f) => f.endsWith('.md'))
    .map((f) => ({ f, text: fs.readFileSync(path.join(EV, f), 'utf8') }));

  const evidenceOnly = all.filter((tool) => {
    const stem = tool.replace(/\.cjs$/, '');
    return !new RegExp('(?<![\\w-])' + stem.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?![\\w-])').test(testCorpus);
  });

  const onlyIndex = [];
  const substantive = [];
  for (const tool of evidenceOnly) {
    const stem = tool.replace(/\.cjs$/, '');
    const docs = evidenceFiles.filter((e) => e.text.includes(stem));
    const real = docs.filter((e) => !GENERATED.test(e.f));
    if (real.length) substantive.push(tool); else if (docs.length) onlyIndex.push(tool);
  }
  return { evidenceOnly, onlyIndex, substantive };
};

test('the evidence-only population is still non-empty', () => {
  const s = scan();
  assert.ok(s.evidenceOnly.length > 20, `only ${s.evidenceOnly.length} evidence-only tools remain`);
  assert.equal(s.onlyIndex.length + s.substantive.length, s.evidenceOnly.length,
    'the two buckets no longer partition the evidence-only population');
});

test('the index-only majority is still the majority', () => {
  const s = scan();
  assert.ok(s.onlyIndex.length > s.substantive.length,
    `index-only ${s.onlyIndex.length} is no longer larger than substantive ${s.substantive.length}`);
  assert.ok(s.onlyIndex.length >= 30, `index-only fell to ${s.onlyIndex.length}`);
});

test('the generated documents really are generated', () => {
  // Each named as generated must actually enumerate tools rather than describe a finding.
  for (const f of ['SCRIPT-INDEX.md', 'TOPIC-INDEX.md']) {
    const text = fs.readFileSync(path.join(ROOT, 'evidence', f), 'utf8');
    assert.ok(!/本轮确立了|measured|结论是/.test(text.slice(0, 2000)),
      `${f} now contains prose findings, so it is not purely an index`);
  }
});

test('the circularity is stated as a rule with its reason', () => {
  assert.match(CIRCULARITY.rule, /not evidence the tool was used/, 'the rule is not stated');
  assert.match(CIRCULARITY.why, /by construction/, 'the reason is not stated');
  assert.match(CIRCULARITY.correctedQuestion, /reason other than enumerating/, 'the corrected question is not stated');
});

test('the gap is recorded as traceability, not as breakage', () => {
  assert.match(GAP.whatIsMissing, /link from finding to instrument/, 'the gap is not named');
  assert.match(GAP.notMissing, /did not fail/, 'the non-defect is not stated');
  assert.ok(GAP.example.includes('proof-consent-hidden') || GAP.example.includes('probe-regwrite'),
    'the example list lost its members');
});

test('the record corrects R630 rather than ignoring it', () => {
  const src = fs.readFileSync(path.join(ROOT, 'desktop', 'index-circularity.cjs'), 'utf8');
  assert.match(src, /true and uninformative/, 'the earlier result is not characterised');
  assert.match(src, /R630/, 'the corrected round is not named');
  assert.ok(src.includes('should be excluded in general'), 'the STATUS caveat is missing');
});
